def bersihkan(df, cols):
    for c in cols:
        df = df.withColumn(c, F.when(F.isnan(c) | (F.col(c) < 0), None).otherwise(F.col(c)))
    df = df.dropna(subset=["kota", "waktu"]).dropDuplicates(["kota", "waktu"])
    w = Window.partitionBy("kota", F.to_date("waktu"))
    for c in cols:
        df = df.withColumn(c, F.coalesce(F.col(c), F.round(F.avg(c).over(w), 2)))
    return df.dropna(subset=cols)

