def query_uji(df):
    return (df.filter((F.col("kota") == "jakarta") & (F.col("bulan") == "2026-03"))
              .groupBy("kota", "bulan")
              .agg(F.count("*").alias("jam"),
                   F.round(F.avg("pm2_5_ug_m3"), 2).alias("rata_pm25"),
                   F.max("pm2_5_ug_m3").alias("maks_pm25")))

